import "server-only";
// Generated by scripts/build-zip-centroids.mjs from the public-domain U.S.
// Census Bureau ZCTA Gazetteer (2025). Server-only so the browser never loads it.
import centroids from "./zip-centroids.json";
import { milesBetweenZips, type Point } from "./miles";

const table = centroids as unknown as Record<string, Point | undefined>;

/** Estimated road miles between two ZIP codes, or null when either is unknown. */
export function estimateMiles(
  fromZip: unknown,
  toZip: unknown,
  roadFactor: number,
) {
  return milesBetweenZips(fromZip, toZip, table, roadFactor);
}
